def error_count(path):
    with open(path) as handle:
        # One line resident at a time; memory is flat regardless of file size.
        return sum(1 for line in handle if " ERROR " in line)

def error_count_bad(path):
    with open(path) as handle:
        # Builds a list of every matching line first, then counts it.
        return len([line for line in handle if " ERROR " in line])
